const item = $input.item.json;
const platform = item.platform;
const message = item.message;
const hashtags = (item.hashtags || []).map((h) => '#' + h).join(' ');
const text = hashtags ? `${message}\n\n${hashtags}` : message;

// TODO: replace these placeholder URLs/bodies with your real, tested platform
// API calls. Prefer n8n's own OAuth2 credential nodes over long-lived tokens
// in environment variables for production use.
const requestsByPlatform = {
  facebook: {
    method: 'POST',
    url: `https://graph.facebook.com/v19.0/${$env.FACEBOOK_PAGE_ID}/feed`,
    body: { message: text, access_token: $env.FACEBOOK_PAGE_ACCESS_TOKEN },
  },
  instagram: {
    // Instagram requires a 2-step Graph API flow (create a media container,
    // then publish it). This placeholder only covers step 1 - split this
    // into two HTTP nodes for a real implementation.
    method: 'POST',
    url: `https://graph.facebook.com/v19.0/${$env.INSTAGRAM_ACCOUNT_ID}/media`,
    body: { caption: text, access_token: $env.INSTAGRAM_ACCESS_TOKEN },
  },
  twitter: {
    method: 'POST',
    url: 'https://api.twitter.com/2/tweets',
    body: { text },
  },
  linkedin: {
    method: 'POST',
    url: 'https://api.linkedin.com/v2/ugcPosts',
    body: {
      author: `urn:li:organization:${$env.LINKEDIN_ORG_ID}`,
      lifecycleState: 'PUBLISHED',
      specificContent: {
        'com.linkedin.ugc.ShareContent': {
          shareCommentary: { text },
          shareMediaCategory: 'NONE',
        },
      },
      visibility: { 'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC' },
    },
  },
  tiktok: {
    method: 'POST',
    url: 'https://open.tiktokapis.com/v2/post/publish/content/init/',
    body: { post_info: { title: text } },
  },
  youtube: {
    // The public YouTube Data API has no simple "text post" endpoint; wire
    // this up to your own video/Shorts upload pipeline if you need it.
    method: 'POST',
    url: 'https://www.googleapis.com/youtube/v3/videos',
    body: { snippet: { description: text } },
  },
};

const request = requestsByPlatform[platform];
if (!request) {
  throw new Error(`No API mapping configured for platform "${platform}"`);
}

return [{
  json: {
    post_id: item.id,
    callback_url: `${$env.ODOO_BASE_URL}/social_media/webhook/posts/${item.id}/result`,
    request,
  },
}];

const context = $('Build Platform Request').item.json;
const current = $input.item.json;
const httpError = current.error;

return [{
  json: {
    post_id: context.post_id,
    callback_url: context.callback_url,
    success: !httpError,
    error: httpError ? String(httpError.message || httpError) : undefined,
  },
}];
